public int[] productExceptSelf(int[] nums) {
    int n = nums.length;
    int[] answer = new int[n];
    answer[0] = 1;
    for (int i = 1; i < n; i++) {
        answer[i] = answer[i - 1] * nums[i - 1];   // product of everything left of i
    }
    int right = 1;                                 // product of everything right of i
    for (int i = n - 1; i >= 0; i--) {
        answer[i] *= right;
        right *= nums[i];
    }
    return answer;
}

public int subarraySum(int[] nums, int k) {
    Map<Integer, Integer> seen = new HashMap<>();   // prefix sum -> how many times seen
    seen.put(0, 1);                                 // empty prefix
    int sum = 0, count = 0;
    for (int x : nums) {
        sum += x;
        count += seen.getOrDefault(sum - k, 0);     // earlier prefixes that leave exactly k
        seen.merge(sum, 1, Integer::sum);
    }
    return count;
}

